diff --git a/source/core/parse-trailer-links.ts b/source/core/parse-trailer-links.ts
new file mode 100644
index 0000000..be85e85
--- /dev/null
+++ b/source/core/parse-trailer-links.ts
@@ -0,0 +1,44 @@
+export default function parseTrailerLinks(link: string) {
+	const parsed = [];
+
+	const items = link.split(',');
+
+	for (const item of items) {
+		// https://tools.ietf.org/html/rfc5988#section-5
+		const [rawUriReference, ...rawLinkParameters] = item.split(';') as [string, ...string[]];
+		const trimmedUriReference = rawUriReference.trim();
+
+		// eslint-disable-next-line @typescript-eslint/prefer-string-starts-ends-with
+		if (trimmedUriReference[0] !== '<' || trimmedUriReference.at(-1) !== '>') {
+			throw new Error(`Invalid format of the trailer Link reference: ${trimmedUriReference}`);
+		}
+
+		const reference = trimmedUriReference.slice(1, -1);
+		const parameters: Record<string, string> = {};
+
+		if (rawLinkParameters.length === 0) {
+			throw new Error(`Unexpected end of trailer Link parameters: ${rawLinkParameters.join(';')}`);
+		}
+
+		for (const rawParameter of rawLinkParameters) {
+			const trimmedRawParameter = rawParameter.trim();
+			const center = trimmedRawParameter.indexOf('=');
+
+			if (center === -1) {
+				throw new Error(`Failed to parse trailer Link: ${link}`);
+			}
+
+			const name = trimmedRawParameter.slice(0, center).trim();
+			const value = trimmedRawParameter.slice(center + 1).trim();
+
+			parameters[name] = value;
+		}
+
+		parsed.push({
+			reference,
+			parameters,
+		});
+	}
+
+	return parsed;
+}
diff --git a/test/parse-trailer-links.ts b/test/parse-trailer-links.ts
new file mode 100644
index 0000000..7e9b42c
--- /dev/null
+++ b/test/parse-trailer-links.ts
@@ -0,0 +1,114 @@
+import test from 'ava';
+import parseTrailerLinks from '../source/core/parse-trailer-links.js';
+
+test('works as expected', t => {
+	t.deepEqual(
+		parseTrailerLinks(
+			'<https://one.example.com>; rel="preconnect", <https://two.example.com>; rel="preconnect", <https://three.example.com>; rel="preconnect"',
+		),
+		[
+			{
+				reference: 'https://one.example.com',
+				parameters: {rel: '"preconnect"'},
+			},
+			{
+				reference: 'https://two.example.com',
+				parameters: {rel: '"preconnect"'},
+			},
+			{
+				reference: 'https://three.example.com',
+				parameters: {rel: '"preconnect"'},
+			},
+		],
+	);
+
+	t.deepEqual(
+		parseTrailerLinks(
+			'<https://one.example.com>; rel="previous"; title="previous chapter"',
+		),
+		[
+			{
+				reference: 'https://one.example.com',
+				parameters: {rel: '"previous"', title: '"previous chapter"'},
+			},
+		],
+	);
+
+	t.deepEqual(
+		parseTrailerLinks('</>; rel="http://example.net/foo"'),
+		[
+			{
+				reference: '/',
+				parameters: {rel: '"http://example.net/foo"'},
+			},
+		],
+	);
+
+	t.deepEqual(
+		parseTrailerLinks('</terms>; rel="copyright"; anchor="#foo"'),
+		[
+			{
+				reference: '/terms',
+				parameters: {rel: '"copyright"', anchor: '"#foo"'},
+			},
+		],
+	);
+
+	t.deepEqual(parseTrailerLinks(`</TheBook/chapter2>;
+	rel="previous"; title*=UTF-8'de'letztes%20Kapitel,
+	</TheBook/chapter4>;
+	rel="next"; title*=UTF-8'de'n%c3%a4chstes%20Kapitel`), [
+		{
+			reference: '/TheBook/chapter2',
+			parameters: {
+				rel: '"previous"',
+				// eslint-disable-next-line @typescript-eslint/quotes, @typescript-eslint/naming-convention
+				'title*': `UTF-8'de'letztes%20Kapitel`,
+			},
+		},
+		{
+			reference: '/TheBook/chapter4',
+			parameters: {
+				rel: '"next"',
+				// eslint-disable-next-line @typescript-eslint/quotes, @typescript-eslint/naming-convention
+				'title*': `UTF-8'de'n%c3%a4chstes%20Kapitel`,
+			},
+		},
+	]);
+
+	t.throws(() => parseTrailerLinks('https://bad.example; rel="preconnect"'), {
+		message: 'Invalid format of the trailer Link reference: https://bad.example',
+	});
+
+	t.throws(() => parseTrailerLinks('https://bad.example; rel'), {
+		message: 'Invalid format of the trailer Link reference: https://bad.example',
+	});
+
+	t.throws(() => parseTrailerLinks('https://bad.example'), {
+		message: 'Invalid format of the trailer Link reference: https://bad.example',
+	});
+
+	t.throws(() => parseTrailerLinks(''), {
+		message: 'Invalid format of the trailer Link reference: ',
+	});
+
+	t.throws(() => parseTrailerLinks('<https://bad.example>; rel'), {
+		message: 'Failed to parse trailer Link: <https://bad.example>; rel',
+	});
+
+	t.throws(() => parseTrailerLinks('<https://bad.example>'), {
+		message: 'Unexpected end of trailer Link parameters: ',
+	});
+
+	t.throws(() => parseTrailerLinks('<>'), {
+		message: 'Unexpected end of trailer Link parameters: ',
+	});
+
+	t.throws(() => parseTrailerLinks('<https://bad.example'), {
+		message: 'Invalid format of the trailer Link reference: <https://bad.example',
+	});
+
+	t.throws(() => parseTrailerLinks('https://bad.example>'), {
+		message: 'Invalid format of the trailer Link reference: https://bad.example>',
+	});
+});
